script:
system_event = {
	id = ancrel.9900
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		NOT = { has_modifier = zroni_storm }
		any_starbase_in_system = {
			has_zroni_storm_caster = yes
		}
	}

	immediate = {
		random_starbase_in_system = {
			limit = {
				has_zroni_storm_caster = yes
			}
			save_event_target_as = storm_caster_starbase
			owner? = {
				save_event_target_as = storm_caster_empire
			}
		}
		if = {
			limit = {
				event_target:storm_caster_empire = {
					NOT = { has_deficit = sr_zro }
				}
			}
			add_modifier = {
				modifier = zroni_storm
				days = -1
			}
			star = {
				create_ambient_object = {
					type = "space_storm_1"
					location = this
				}
			}
			last_created_ambient_object = {
				set_ambient_object_flag = zroni_storm
				set_location = {
					target = prev
					distance = 0
					angle = random
				}
			}
			if = {
				limit = {
					event_target:storm_caster_empire = {
						has_ascension_perk = ap_archaeoengineers
					}
				}
				event_target:storm_caster_starbase = {
					add_starbase_component = {
						component = "STARBASE_AURA_ZRONI_STORM"
					}
				}
			}
		}
	}
}

